public class CategoryFilterPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    static String contents(java.awt.Component c) {
        if (!(c instanceof javax.swing.JList)) {
            return "(missing)";
        }
        javax.swing.ListModel<?> m = ((javax.swing.JList<?>) c).getModel();
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < m.getSize(); i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(m.getElementAt(i));
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        try {
            CategoryFilterPanel panel = new CategoryFilterPanel();
            java.awt.Component comboComp = find(panel, "category");
            java.awt.Component listComp = find(panel, "results");
            java.awt.Component label = find(panel, "count");
            check("combo box found", true, comboComp instanceof javax.swing.JComboBox);
            check("everything shown at startup", "[Apple, Banana, Carrot, Cherry, Daikon, Endive]",
                    contents(listComp));
            check("startup count label", "6 of 6 shown", labelText(label));
            if (comboComp instanceof javax.swing.JComboBox) {
                javax.swing.JComboBox<?> combo = (javax.swing.JComboBox<?>) comboComp;
                check("three categories offered", 3, combo.getItemCount());
                combo.setSelectedItem("fruit");
                check("fruit only", "[Apple, Banana, Cherry]", contents(listComp));
                check("fruit count label", "3 of 6 shown", labelText(label));
                combo.setSelectedIndex(2);
                check("veg only", "[Carrot, Daikon, Endive]", contents(listComp));
                combo.setSelectedIndex(0);
                check("back to everything", "6 of 6 shown", labelText(label));
            } else {
                failures++;
                System.out.println("FAIL  category combo not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

