import javax.swing.DefaultListModel;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;

class Produce {
    final String name;
    final String kind;

    Produce(String name, String kind) {
        this.name = name;
        this.kind = kind;
    }
}

public class CategoryFilterPanel extends JPanel {

    private static final Produce[] ITEMS = {
        new Produce("Apple", "fruit"),
        new Produce("Banana", "fruit"),
        new Produce("Carrot", "veg"),
        new Produce("Cherry", "fruit"),
        new Produce("Daikon", "veg"),
        new Produce("Endive", "veg")
    };

    private final JComboBox<String> category = new JComboBox<>(new String[] { "All", "fruit", "veg" });
    private final DefaultListModel<String> shown = new DefaultListModel<>();
    private final JList<String> results = new JList<>(shown);
    private final JLabel count = new JLabel("(not filtered)");

    public CategoryFilterPanel() {
        category.setName("category");
        results.setName("results");
        count.setName("count");
        add(category);
        add(results);
        add(count);
        category.addActionListener(e -> applyFilter());
        applyFilter();
    }

    public void applyFilter() {
        String chosen = (String) category.getSelectedItem();
        shown.clear();
        for (Produce item : ITEMS) {
            if ("All".equals(chosen) || item.kind.equals(chosen)) {
                shown.addElement(item.name);
            }
        }
        count.setText(shown.getSize() + " of " + ITEMS.length + " shown");
    }
}
